-module(nourish_page).
-behaviour(cowboy_handler).
-export([init/2]).

init(Req0, []) ->
    Body = <<"<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Nourish Network</title><link rel='stylesheet' href='https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;600;700;800&display=swap'><style>
    :root{--green:#145c45;--ink:#18342d;--muted:#6b7d75;--line:#e4ebe6;--cream:#f5f7f2}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:15px 'DM Sans',sans-serif}header{background:#fff;border-bottom:1px solid var(--line)}.bar{max-width:1120px;margin:auto;padding:18px 24px;display:flex;align-items:center;justify-content:space-between}.brand{font:800 23px Manrope,sans-serif;color:var(--green)}.brand span{color:#d58a47}.tag{color:var(--muted);font-size:13px}.wrap{max-width:1120px;margin:40px auto;padding:0 24px}.hero{display:flex;justify-content:space-between;gap:32px;align-items:end;margin-bottom:28px}.eyebrow{text-transform:uppercase;letter-spacing:.13em;color:#56806c;font-weight:700;font-size:11px}.hero h1{font:800 38px Manrope,sans-serif;margin:10px 0}.hero p{color:var(--muted);margin:0}.button{border:0;border-radius:10px;background:var(--green);color:white;padding:13px 18px;font-weight:700;cursor:pointer}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:24px 0}.metric,.panel{background:white;border:1px solid var(--line);border-radius:16px;padding:20px}.metric b{display:block;font:800 25px Manrope}.metric span{color:var(--muted);font-size:13px}.section{display:flex;justify-content:space-between;align-items:center;margin:30px 0 14px}.section h2{font:700 21px Manrope;margin:0}.section small{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:19px}.pill{display:inline-block;padding:5px 9px;border-radius:20px;background:#e8f3eb;color:#28704d;font-size:11px;font-weight:700}.pill.discount{background:#fff1df;color:#956123}.card h3{font:700 18px Manrope;margin:13px 0 5px}.business{color:var(--muted)}.details{border-top:1px solid var(--line);margin-top:16px;padding-top:14px;display:grid;gap:8px;font-size:13px}.detail{display:flex;justify-content:space-between;gap:10px}.detail span:first-child{color:var(--muted)}.claim{margin-top:16px;width:100%;border:1px solid var(--green);background:white;color:var(--green);border-radius:9px;padding:10px;font-weight:700;cursor:pointer}.claim:hover{background:#f1f7f2}.empty{grid-column:1/-1;padding:44px;text-align:center;color:var(--muted)}.shade{position:fixed;inset:0;background:#10271f66;display:none;align-items:center;justify-content:center;padding:20px}.modal{background:white;border-radius:18px;padding:25px;width:min(460px,100%)}.modal h2{font:700 23px Manrope;margin:0 0 18px}.modal label{display:block;font-weight:600;font-size:13px;margin:12px 0 5px}.modal input,.modal select,.modal textarea{width:100%;padding:11px;border:1px solid var(--line);border-radius:8px;font:inherit}.modal textarea{min-height:70px}.actions{display:flex;justify-content:end;gap:10px;margin-top:18px}.secondary{background:white;border:1px solid var(--line);color:var(--ink)}@media(max-width:750px){.grid{grid-template-columns:repeat(2,1fr)}.hero{align-items:start;flex-direction:column}.wrap{margin:26px auto}.hero h1{font-size:31px}}@media(max-width:520px){.grid{grid-template-columns:1fr}.metrics{gap:8px}.metric{padding:14px}.metric b{font-size:21px}.tag{display:none}}
    </style></head><body><header><div class='bar'><div class='brand'>nourish<span>.</span></div><div class='tag'>Good food finds a table.</div></div></header><main class='wrap'><div class='hero'><div><div class='eyebrow'>Neighborhood food rescue</div><h1>Rescue good food.<br>Feed your community.</h1><p>Fresh local offers, ready for their next home.</p></div><button class='button' id='newOffer'>+ Post surplus food</button></div><div class='metrics'><div class='metric'><b id='pickupCount'>0</b><span>Pickups completed</span></div><div class='metric'><b id='quantityTotal'>0</b><span>Items rescued</span></div><div class='metric'><b id='offerCount'>0</b><span>Available nearby</span></div></div><div class='section'><h2>Available food</h2><small>Live neighborhood offers</small></div><div class='grid' id='offers'><div class='empty'>Loading today's offers...</div></div></main><div class='shade' id='shade'><form class='modal' id='offerForm'><h2>Share surplus food</h2><label>Business</label><input name='business' required placeholder='e.g. Northside Market'><label>What is available?</label><input name='title' required placeholder='e.g. Bakery and produce box'><label>Quantity and unit</label><div style='display:flex;gap:8px'><input name='quantity' type='number' min='1' required placeholder='8'><input name='unit' required placeholder='boxes'></div><label>Pickup by</label><input name='pickup_by' type='datetime-local' required><label>Pickup address</label><input name='address' required placeholder='Street address'><label>Offer type</label><select name='kind'><option value='donation'>Free donation</option><option value='discount'>Discounted</option></select><label>Notes (optional)</label><textarea name='notes' placeholder='Allergen or handling notes'></textarea><div class='actions'><button type='button' class='button secondary' id='close'>Cancel</button><button class='button'>Publish offer</button></div></form></div><script src='/assets/app.js'></script></body></html>">>,
    Req = cowboy_req:reply(200, #{<<"content-type">> => <<"text/html; charset=utf-8">>}, Body, Req0),
    {ok, Req, undefined};
init(Req0, [js]) ->
    Body = <<"const offersEl=document.querySelector('#offers');let offers=[];const fmtDate=s=>new Date(s).toLocaleString([], {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});function render(){document.querySelector('#offerCount').textContent=offers.length;offersEl.innerHTML=offers.length?offers.map(o=>`<article class=\"card\"><span class=\"pill ${o.kind==='discount'?'discount':''}\">${o.kind==='discount'?'Discounted':'Free donation'}</span><h3>${esc(o.title)}</h3><div class=\"business\">${esc(o.business)}</div><div class=\"details\"><div class=\"detail\"><span>Available</span><b>${o.quantity} ${esc(o.unit)}</b></div><div class=\"detail\"><span>Pickup by</span><b>${fmtDate(o.pickup_by)}</b></div><div class=\"detail\"><span>Location</span><b>${esc(o.address)}</b></div></div><button class=\"claim\" onclick=\"claim('${o.id}')\">Claim pickup</button></article>`).join(''):'<div class=\"empty\">No offers right now. Check back soon, or post surplus food.</div>'}function esc(s){return String(s||'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}async function load(){offers=await(await fetch('/api/offers')).json();render();const i=await(await fetch('/api/impact')).json();document.querySelector('#pickupCount').textContent=i.completed_pickups;document.querySelector('#quantityTotal').textContent=Object.entries(i.quantities_by_unit||{}).map(([u,n])=>`${n} ${u}`).join(', ')||'0'}async function claim(id){const recipient=prompt('Your organization or name:');if(!recipient)return;const r=await fetch(`/api/offers/${id}/claim`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({recipient})});if(r.ok)load();else alert('This offer has already been claimed or expired.')}document.querySelector('#newOffer').onclick=()=>document.querySelector('#shade').style.display='flex';document.querySelector('#close').onclick=()=>document.querySelector('#shade').style.display='none';document.querySelector('#offerForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),o=Object.fromEntries(f);o.quantity=Number(o.quantity);o.pickup_by=new Date(o.pickup_by).toISOString();const r=await fetch('/api/offers',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(o)});if(r.ok){e.target.reset();document.querySelector('#shade').style.display='none';load()}else alert('Please check the offer details.')};const events=new EventSource('/api/events');events.onmessage=()=>load();load();">>,
    Req = cowboy_req:reply(200, #{<<"content-type">> => <<"application/javascript; charset=utf-8">>}, Body, Req0),
    {ok, Req, undefined}.
